+        case ASR::exprType::IntegerUnaryMinus:
+        case ASR::exprType::RealUnaryMinus:
+        case ASR::exprType::ComplexUnaryMinus:
+        case ASR::exprType::Var: {
+            return true;
+        }
+        default: {
+            return false;
+        }
+    }
